## Why This Is Asked
Explores a practical, augmented Trie approach blending prefix queries with order-statistics, a gap in typical BST/trie questions.

## Key Concepts
- Trie augmentation with endCount and subCount
- Duplicates handled via endCount
- Lexicographic kthWord via endCount before children

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.end = 0;
    this.sub = 0;
  }
}
class Trie {
  constructor(){ this.root = new Node(); }
  insert(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  delete(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  countPrefix(p){ let cur=this.root; for(const ch of p){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
  kthWord(k){ let res=''; let node=this.root; while(true){ if(k <= node.end) return res; k -= node.end; // skip words ending here
      // iterate in lexical order
      const keys = Array.from(node.next.keys()).sort();
      for(const ch of keys){ const child=node.next.get(ch); if(child.sub >= k){ res += ch; node = child; break; } else k -= child.sub; }
    }
  }
}
```

## Follow-up Questions
- How would you adapt for Unicode or larger alphabets?
- What are memory implications for dense vs sparse alphabets?
- How would you support delete of non-existent words without errors?

## Why This Question Is Asked
This problem evaluates the ability to extend classic DP patterns (like the staircase problem) with an additional resource dimension, while also testing space optimization skills and recursive thinking via memoization. It distinguishes candidates who understand both bottom-up and top-down approaches, and who reason through edge cases systematically.

## Key Concepts
- DP with an extra budget constraint (two-dimensional state: position + accumulated cost)
- Space optimization using rolling arrays to reduce O(n·B) space to O(B)
- Memoization on composite state (i, b) for the recursive variant
- Correct base case handling when starting from a virtual position before index 0

## Code Example
```javascript
const MOD = 1_000_000_007n;

function countWays(cost, B) {
  const n = cost.length;
  if (n === 0) return 0;

  // bottom-up with rolling arrays
  let prev2 = new Array(B + 1).fill(0);
  let prev1 = new Array(B + 1).fill(0);

  // base: step 0
  if (cost[0] <= B) prev2[cost[0]] = 1;

  // base: step 1
  if (n > 1 && cost[1] <= B) prev1[cost[1]] = 1;

  // step 2 onwards
  for (let i = 2; i < n; i++) {
    const cur = new Array(B + 1).fill(0);
    for (let b = cost[i]; b <= B; b++) {
      cur[b] = (prev1[b - cost[i]] + prev2[b - cost[i]]) % MOD;
    }
    prev2 = prev1;
    prev1 = cur;
  }

  return n === 1 ? prev2[B] : prev1[B];
}

// memoized DFS variant
function countWaysDFS(cost, B) {
  const n = cost.length;
  const memo = new Map();

  function dfs(i, b) {
    if (b < 0) return 0;
    if (i < 0) return b === 0 ? 1 : 0;
    const key = `${i},${b}`;
    if (memo.has(key)) return memo.get(key);
    const result = (dfs(i - 1, b - cost[i]) + dfs(i - 2, b - cost[i])) % MOD;
    memo.set(key, result);
    return result;
  }

  return dfs(n - 1, B);
}
```

## Why This Is Asked
This problem assesses mastery of graph algorithms on DAGs, including topological sorting, feasibility verification under ordered constraints, and shortest-path computation.

## Key Concepts
- Topological sort for DAGs
- DAG shortest-path DP (O(|V| + |E|))
- Feasibility checking with ordered mandatory edges
- Path reconstruction via predecessor pointers

## Code Example
```javascript
function shortestConstrainedPath(G, S, T, M) {
  const topo = topoSort(G);
  const idx = (v) => topo.indexOf(v);

  const canReach = (from, to) => {
    if (idx(from) >= idx(to)) return false;
    const reachable = new Set([from]);
    for (let i = idx(from); i < idx(to); i++) {
      for (const edge of G.adj[topo[i]]) {
        if (idx(edge.to) < idx(to)) reachable.add(edge.to);
      }
    }
    return reachable.has(to);
  };

  const points = [S, ...M.map(e => e[0]), ...M.map(e => e[1]), T];
  for (let i = 0; i < points.length - 1; i++) {
    if (!canReach(points[i], points[i + 1])) return null;
  }

  const segmentCost = (src, dst) => {
    const dist = {}; dist[src] = 0;
    for (let i = idx(src); i < idx(dst); i++) {
      const u = topo[i];
      for (const edge of G.adj[u]) {
        if (idx(edge.to) < idx(dst)) {
          if (dist[u] + edge.w < (dist[edge.to] ?? Infinity)) {
            dist[edge.to] = dist[u] + edge.w;
          }
        }
      }
    }
    return dist[dst];
  };

  let total = 0;
  const fullPath = [S];
  for (const [u, v, w] of M) {
    total += w;
    const seg = segmentCost(fullPath[fullPath.length - 1], u);
    if (seg === undefined) return null;
    total += seg;
  }
  const finalSeg = segmentCost(M[M.length - 1][1], T);
  if (finalSeg === undefined) return null;
  return total + finalSeg;
}
```

## Why This Is Asked
Assesses the ability to blend Trie prefix search with balanced BSTs for dynamic scores, plus a top-k retrieval strategy that scales efficiently. It tests practical update propagation and memory trade-offs in a high-throughput autocomplete system.

## Key Concepts
- Trie for prefix lookup
- AVL/balanced BST per node for phrase-score storage
- Top-k extraction via a front-to-back heap or subtree aggregation
- Update propagation costs and memory considerations

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.words = new AVLTree(); // key: phrase, value: score
    this.topK = new MaxHeap(k); // top-k scores for subtree
  }
}

class AutoCompleteDictionary {
  constructor(k = 10) {
    this.root = new TrieNode();
    this.k = k;
  }

  insertPhrase(phrase, score) {
    let node = this.root;
    for (let char of phrase) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.words.insert(phrase, score);
      node.topK.insert(score);
    }
  }

  queryTopK(prefix, k) {
    let node = this.root;
    for (let char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    return node.topK.getTopK(k);
  }
}
```

## Time Complexity Analysis
- insertPhrase: O(L log n) where L is phrase length, n is phrases per prefix
- updateScore: O(L log n) for BST updates plus O(L) for heap propagation
- deletePhrase: O(L log n) for BST removal and heap cleanup
- queryTopK: O(L + k log k) for traversal plus heap extraction

## Memory Trade-offs
- Trie structure: O(N × L) where N is total phrases, L is average length
- BST per node: O(N) total across all nodes
- Top-k heaps: O(N × k) worst-case, but typically O(N) with pruning

## Edge Cases
- Duplicate phrases: update existing entry instead of inserting
- Score ties: use lexicographic ordering as tiebreaker
- Empty prefix: return global top-k from root node
- Large k: consider segment tree for better range queries

## Comparison with Alternatives
- Hash map + sorting: O(1) insert but O(n log n) prefix queries
- Suffix tree: better substring search but higher memory overhead
- Pure Trie with scores: O(L) queries but O(n) updates for score changes
- Hybrid approach (proposed): balances prefix efficiency with dynamic updates

## Why This Is Asked

Tests ability to reason about DAGs, timing, and dynamic programming over graphs, a common pattern in build pipelines, data workflows, or task scheduling.

## Key Concepts

- Topological sort to linearize a DAG
- DP on DAG to propagate earliest start times
- In-degree based BFS (Kahn) and cycle detection

## Code Example

```javascript
function earliestTimes(n, duration, edges) {
  const g = Array.from({length: n}, () => []);
  const indeg = Array(n).fill(0);
  for (const [u, v] of edges) { g[u].push(v); indeg[v]++; }
  const es = Array(n).fill(0);
  const q = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
  let visited = 0;
  while (q.length) {
    const u = q.shift();
    visited++;
    for (const v of g[u]) {
      es[v] = Math.max(es[v], es[u] + duration[u]);
      if (--indeg[v] === 0) q.push(v);
    }
  }
  const total = Math.max(...es.map((s, i) => s + duration[i]));
  return { earliestStart: es, totalDuration: total };
}
```

## Follow-up Questions

- How would you adapt to detect cycles and report the cycle path?
- How would you extend to handle parallel resources or varying durations per edge?

## Why This Is Asked
This tests building a Trie and adding an autocomplete-style suggest method, a common real-world need.

## Key Concepts
- Trie nodes with 26 children; end-of-word markers; storing full word for suggestions
- Lexicographic DFS for deterministic suggestions
- Complexity and memory trade-offs; edge cases like no matches

## Code Example
```javascript
class TrieNode {
  constructor(){ this.children = new Map(); this.isWord=false; this.word=null }
}
class Trie {
  constructor(){ this.root=new TrieNode(); }
  insert(word){ let n=this.root; for (let ch of word){ if(!n.children.has(ch)) n.children.set(ch,new TrieNode()); n=n.children.get(ch); } n.isWord=true; n.word=word; }
  search(word){ let n=this.root; for(let ch of word){ if(!n.children.has(ch)) return false; n=n.children.get(ch); } return n.isWord; }
  startsWith(prefix){ let n=this.root; for(let ch of prefix){ if(!n.children.has(ch)) return false; n=n.children.get(ch); } return true; }
  suggest(prefix, limit){ let n=this.root; for(let ch of prefix){ if(!n.children.has(ch)) return []; n=n.children.get(ch); }
    const res=[];
    const dfs=(cur, path)=>{ if(res.length>=limit) return; if(cur.isWord) res.push(prefix+path); const keys=Array.from(cur.children.keys()).sort(); for(let c of keys){ dfs(cur.children.get(c), path+c); } };
    dfs(n, '');
    return res;
  }
}
```

